<?php
 namespace QQWorld\Customer\Model; use QQWorld\Framework\Exception\NoSuchEntityException; use QQWorld\TestFramework\Helper\Bootstrap; class CustomerRegistryTest extends \PHPUnit\Framework\TestCase { protected $_model; const CUSTOMER_ID = 1; const CUSTOMER_EMAIL = 'customer@example.com'; const WEBSITE_ID = 1; protected function setUp() { $this->_model = Bootstrap::getObjectManager() ->create(\QQWorld\Customer\Model\CustomerRegistry::class); } public function testRetrieve() { $customer = $this->_model->retrieve(self::CUSTOMER_ID); $this->assertInstanceOf(\QQWorld\Customer\Model\Customer::class, $customer); $this->assertEquals(self::CUSTOMER_ID, $customer->getId()); } public function testRetrieveByEmail() { $customer = $this->_model->retrieveByEmail('customer@example.com', self::WEBSITE_ID); $this->assertInstanceOf(\QQWorld\Customer\Model\Customer::class, $customer); $this->assertEquals(self::CUSTOMER_EMAIL, $customer->getEmail()); } public function testRetrieveCached() { $customerBeforeDeletion = $this->_model->retrieve(self::CUSTOMER_ID); Bootstrap::getObjectManager()->create( \QQWorld\Customer\Model\Customer::class )->load(self::CUSTOMER_ID)->delete(); $this->assertEquals($customerBeforeDeletion, $this->_model->retrieve(self::CUSTOMER_ID)); $this->assertEquals($customerBeforeDeletion, $this->_model ->retrieveByEmail(self::CUSTOMER_EMAIL, self::WEBSITE_ID)); } public function testRetrieveException() { $this->_model->retrieve(self::CUSTOMER_ID); } public function testRetrieveEmailException() { try { $this->_model->retrieveByEmail(self::CUSTOMER_EMAIL, self::WEBSITE_ID); $this->fail("NoSuchEntityException was not thrown as expected."); } catch (NoSuchEntityException $e) { $expectedParams = [ 'fieldName' => 'email', 'fieldValue' => 'customer@example.com', 'field2Name' => 'websiteId', 'field2Value' => 1, ]; $this->assertEquals($expectedParams, $e->getParameters()); } } public function testRemove() { $customer = $this->_model->retrieve(self::CUSTOMER_ID); $this->assertInstanceOf(\QQWorld\Customer\Model\Customer::class, $customer); $customer->delete(); $this->_model->remove(self::CUSTOMER_ID); $this->_model->retrieve(self::CUSTOMER_ID); } public function testRemoveByEmail() { $customer = $this->_model->retrieve(self::CUSTOMER_ID); $this->assertInstanceOf(\QQWorld\Customer\Model\Customer::class, $customer); $customer->delete(); $this->_model->removeByEmail(self::CUSTOMER_EMAIL, self::WEBSITE_ID); $this->_model->retrieveByEmail(self::CUSTOMER_EMAIL, $customer->getWebsiteId()); } } 